pub(crate) fn task_completion_success(task: &BenchmarkTaskDescriptor, run: &AgentRun) -> bool {
    run.state == AgentRunState::Completed
        && completion_report_satisfies_task(task, &run.completion, run.validation_attempts.len())
        && task_specific_evidence_satisfied(task.kind, run)
}

fn task_specific_evidence_satisfied(kind: BenchmarkTaskKind, run: &AgentRun) -> bool {
    match kind {
        BenchmarkTaskKind::ReadQuestion => false,
        BenchmarkTaskKind::ProjectInspection => {
            run.audit.authoring_operations > 0 && run.audit.raw_workspace_operations == 0
        }
        BenchmarkTaskKind::CodeImplementation => run.audit.code_changes > 0,
        BenchmarkTaskKind::TypedAuthoringMutation => {
            run.audit.authoring_operations > 0 && run.audit.raw_workspace_operations == 0
        }
        BenchmarkTaskKind::ValidationRepair => {
            run.audit.code_changes > 0
                && run.validation_attempts.len() >= 2
                && run
                    .validation_attempts
                    .first()
                    .is_some_and(|attempt| attempt.status == ManagedValidationAttemptStatus::Failed)
                && run
                    .validation_attempts
                    .last()
                    .is_some_and(|attempt| attempt.status == ManagedValidationAttemptStatus::Passed)
        }
        BenchmarkTaskKind::RuntimeInteraction => run.audit.managed_runtime_inputs > 0,
        BenchmarkTaskKind::VisualEvaluation => run.events.iter().any(|event| {
            matches!(event.evidence, Some(AgentEventEvidence::CapturedFrame { .. }))
        }),
    }
}

fn explicit_oom_message(message: &str) -> bool {
    let message = message.to_ascii_lowercase();
    message.contains("out of memory")
        || message.contains("cuda oom")
        || message.contains("gpu oom")
        || message
            .split(|character: char| !character.is_ascii_alphanumeric())
            .any(|word| word == "oom")
}

